"use client";
import { useRef, useState, useTransition } from "react";
import type { PlanningTask } from "@/lib/data/planning";
import { addPlanningTask, updatePlanningTask, removePlanningTask } from "@/app/admin/(dashboard)/vendors/actions";
export function PlanningTasks({ tasks, vendors, canEdit, today }: { tasks: PlanningTask[]; vendors: Array<{ id: string; name: string }>; canEdit: boolean; today: string }) {
  const [state, setState] = useState<{ok?:boolean;message?:string}>({}); const [adding, addStart] = useTransition(); const [pending, start] = useTransition(); const [message, setMessage] = useState("");
  const operation = useRef<{fingerprint:string;id:string}|null>(null);
  function add(form: HTMLFormElement) {
    if (adding) return;
    const data = new FormData(form); const fingerprint = JSON.stringify([...data.entries()]);
    if (operation.current?.fingerprint !== fingerprint) operation.current = { fingerprint, id: crypto.randomUUID() };
    data.set("operationId", operation.current.id);
    addStart(async () => { try { const result = await addPlanningTask({}, data); setState(result); if (result.ok) { form.reset(); operation.current = null; } } catch { setState({ok:false,message:"The result could not be confirmed. Retry this draft safely, or refresh."}); } });
  }
  const field = "rounded-lg border border-hairline bg-white p-2 text-sm";
  function run(action: () => Promise<{ ok?: boolean; message?: string }>) { start(async () => { try { const r = await action(); setMessage(r.message ?? "Saved."); } catch { setMessage("The change could not be confirmed. Refresh before retrying."); } }); }
  return <section className="flex flex-col gap-4"><h2 className="text-lg font-semibold">Planning tasks</h2>{message && <p role="status" className="text-sm text-rose-deep">{message}</p>}
    {tasks.map(t => <article key={t.id} className={`rounded-xl border border-hairline p-4 ${!t.completed_at && t.due_date && t.due_date < today ? "bg-blush/40" : "bg-paper/40"}`}><div className="flex gap-3"><h3 className={`flex-1 font-medium ${t.completed_at ? "line-through text-muted" : ""}`}>{t.title}</h3>{canEdit && <button disabled={pending} onClick={() => run(() => updatePlanningTask(t.id, { complete: !t.completed_at }))} className="text-sm text-olive underline">{t.completed_at ? "Reopen" : "Complete"}</button>}</div><p className="mt-1 text-sm text-muted">{t.due_date ?? "No due date"}{t.assigned_to ? ` · ${t.assigned_to}` : ""}{t.vendor_id ? ` · ${vendors.find(v => v.id === t.vendor_id)?.name ?? "Vendor"}` : ""}</p>{t.notes && <p className="mt-2 whitespace-pre-wrap text-sm">{t.notes}</p>}
      {canEdit && <details className="mt-3"><summary className="cursor-pointer text-sm text-olive">Edit task</summary><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); run(() => updatePlanningTask(t.id, { title: String(f.get("title")), dueDate: String(f.get("dueDate")) || null, assignedTo: String(f.get("assignedTo")) || null, notes: String(f.get("notes")) || null })); }} className="mt-3 grid gap-2"><label className="text-sm">Task<input disabled={adding} required name="title" defaultValue={t.title} className={`${field} block w-full`} /></label><label className="text-sm">Due date<input disabled={adding} name="dueDate" type="date" defaultValue={t.due_date ?? ""} className={`${field} ml-2`} /></label><label className="text-sm">Responsible person<input disabled={adding} name="assignedTo" defaultValue={t.assigned_to ?? ""} className={`${field} block w-full`} /></label><label className="text-sm">Notes<textarea disabled={adding} name="notes" defaultValue={t.notes ?? ""} className={`${field} block w-full`} /></label><button disabled={pending} className={field}>Save task</button></form><button disabled={pending} onClick={() => { if (confirm(`Delete task “${t.title}”?`)) run(() => removePlanningTask(t.id)); }} className="mt-3 text-sm text-rose-deep">Delete task</button></details>}
    </article>)}
    {!tasks.length && <p className="text-sm text-muted">No tasks yet. Add a deadline or follow-up below.</p>}
    {canEdit && <form onSubmit={event => { event.preventDefault(); add(event.currentTarget); }} className="grid gap-3 rounded-xl border border-hairline p-4 md:grid-cols-2"><h3 className="font-medium md:col-span-2">Add a task</h3>{state.message && <p role={state.ok ? "status" : "alert"} className="text-sm md:col-span-2">{state.message}</p>}<label className="text-sm">Task<input disabled={adding} required name="title" maxLength={300} className={`${field} block w-full`} /></label><label className="text-sm">Due date<input disabled={adding} type="date" name="dueDate" className={`${field} block w-full`} /></label><label className="text-sm">Responsible person<input disabled={adding} name="assignedTo" className={`${field} block w-full`} /></label><label className="text-sm">Vendor<select disabled={adding} name="vendorId" className={`${field} block w-full`}><option value="">General planning</option>{vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}</select></label><label className="text-sm md:col-span-2">Notes<textarea disabled={adding} name="notes" className={`${field} block w-full`} /></label><button disabled={adding} className="rounded-lg bg-olive-deep p-2 text-sm text-cream md:col-span-2">{adding ? "Adding…" : "Add task"}</button></form>}
  </section>;
}
